package dev.eugheist.ttmodern;
import net.minecraft.world.item.*;
import net.minecraft.world.entity.*;
import thaumcraft.api.aspects.*;
final class KamiArmorAudit {
 static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT KAMI armor: "+label);}
 static void run(net.minecraft.server.MinecraftServer server){var level=server.overworld();var player=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(level);player.getInventory().clearContent();player.removeAllEffects();String[] keys={"ICHORCLOTH_HELM","ICHORCLOTH_CHEST","ICHORCLOTH_LEGS","ICHORCLOTH_BOOTS"},patterns={"CCCC C   ","C CCCCCCC","CCCC CC C","C CC C   "};Aspect[] costs={Aspect.WATER,Aspect.AIR,Aspect.FIRE,Aspect.EARTH};int[] defense={3,8,6,3};var wand=dev.eugheist.tc4modern.WandParts.make(dev.eugheist.tc4modern.WandParts.CAPS.get("gold"),dev.eugheist.tc4modern.WandParts.RODDEFS.get("greatwood"));float plain=dev.eugheist.tc4modern.WandData.craftingModifier(wand,player,Aspect.AIR);
 for(int i=0;i<4;i++){var item=KamiArmor.ITEMS.get(i).get();var stack=new ItemStack(item);check(item.getDefense()==defense[i]&&item.getEnchantmentValue()==20&&stack.hasFoil()&&stack.getRarity()==Rarity.EPIC&&!stack.isDamageableItem(),"original piece protection/enchantability/foil/rarity/unbreakable");stack.hurtAndBreak(9999,level,null,x->{});check(stack.getCount()==1&&stack.getDamageValue()==0,"native durability immunity");var restored=ItemStack.parseOptional(server.registryAccess(),(net.minecraft.nbt.CompoundTag)stack.save(server.registryAccess()));check(restored.is(item)&&!restored.isDamageableItem(),"native persistence");player.setItemSlot(item.getEquipmentSlot(),stack);var grid=new java.util.ArrayList<ItemStack>();for(char c:patterns[i].toCharArray())grid.add(c==' '?ItemStack.EMPTY:new ItemStack(KamiResources.item(KamiResources.Kind.CLOTH)));var recipe=dev.eugheist.tc4modern.ArcaneRecipes.find(grid,java.util.Set.of("ICHORCLOTH_ARMOR"));check(recipe!=null&&recipe.key().equals(keys[i])&&recipe.output().is(item)&&recipe.cost().size()==1&&recipe.cost().getAmount(costs[i])==75&&dev.eugheist.tc4modern.ArcaneRecipes.find(grid,java.util.Set.of())==null,"original native recipe/cost/lock");}
 for(var aspect:Aspect.getPrimalAspects())check(Math.abs(plain-dev.eugheist.tc4modern.WandData.craftingModifier(wand,player,aspect)-.15f)<1e-5,"actual universal full set15percent");player.getInventory().clearContent();
 var target=EntityType.COW.create(level);target.setNoAi(true);target.setPos(24,290,24);target.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(100);level.addFreshEntity(target);
 try{for(int mode=0;mode<6;mode++){for(var type:KamiArmor.TYPES)target.setItemSlot(type.getSlot(),ItemStack.EMPTY);target.setItemSlot(EquipmentSlot.HEAD,new ItemStack(KamiArmor.ITEMS.getFirst().get()));if(mode!=0){for(var item:KamiArmor.ITEMS)target.setItemSlot(item.get().getEquipmentSlot(),new ItemStack(item.get()));}if(mode==3)target.setItemSlot(EquipmentSlot.FEET,new ItemStack(Items.DIAMOND_BOOTS));if(mode>=4)target.setItemSlot(EquipmentSlot.HEAD,new ItemStack(dev.eugheist.tc4modern.FortressArmor.item("helmet")));target.tick();target.setHealth(100);target.invulnerableTime=0;boolean magic=mode==2||mode==5;check(target.hurt(magic?level.damageSources().magic():level.damageSources().mobAttack(target),10),"native hit accepted");float expected=mode==0?8.725f:mode==3||mode==4?1.575f:mode==5?(float)(10*(1-3/35d)*(1-17*.0425)):1.5f;check(Math.abs((100-target.getHealth())-expected)<1e-4,"actual original absorption mode"+mode+" got "+(100-target.getHealth()));for(var stack:target.getArmorSlots())if(stack.getItem() instanceof KamiArmor)check(stack.getDamageValue()==0,"native armor hit no damage");}
 for(var type:KamiArmor.TYPES)target.setItemSlot(type.getSlot(),ItemStack.EMPTY);target.setItemSlot(EquipmentSlot.HEAD,new ItemStack(KamiArmor.ITEMS.getFirst().get()));var worn=new ItemStack(Items.DIAMOND_BOOTS);worn.setDamageValue(worn.getMaxDamage()-1);target.setItemSlot(EquipmentSlot.FEET,worn);target.tick();target.setHealth(100);target.invulnerableTime=0;check(target.hurt(level.damageSources().mobAttack(target),10),"near-broken mixed hit");check(Math.abs((100-target.getHealth())-8.645f)<1e-4&&target.getItemBySlot(EquipmentSlot.FEET).isEmpty(),"original normal armor remaining-durability cap and break");check(target.getItemBySlot(EquipmentSlot.HEAD).getDamageValue()==0,"KAMI survives normal armor break");
 }finally{target.discard();}
 var r=thaumcraft.api.research.ResearchCategories.getResearch("ICHORCLOTH_ARMOR");check(r instanceof KamiResearch&&r.displayColumn==17&&r.displayRow==5&&java.util.Arrays.equals(r.parents,new String[]{"ICHOR_CLOTH"})&&r.getPages().length==5&&dev.eugheist.tc4modern.ResearchWarp.amount(r.key)==4,"research/page/warp");System.out.println("TT KAMI ARMOR AUDIT: ALL PASS (four recipes/locks/costs,persistence/durability,real gear15percent,actual single/full/mixed/magic absorption,research/warp)");}
}
